import {
  createContext, useContext, useState,
  useCallback, useEffect, ReactNode
} from "react"

// ── TIPOS ────────────────────────────────────────────────
export type ReadingMode  = "night" | "twilight" | "dawn"
export type FontSize     = "small" | "medium" | "large"
export type LineSpacing  = "compact" | "normal" | "relaxed"
export type AppLanguage  = "es" | "en" | "fr" | "de" | "it" | "pt" | "ja" | "zh" | "ar"
export const SUPPORTED_UI_LANGUAGES: AppLanguage[] = ["es","en","fr","de","it","pt","ja","zh","ar"]

export interface Settings {
  readingMode:     ReadingMode
  fontSize:        FontSize
  orbSounds:       boolean
  soundVolume:     number
  musicEnabled:    boolean
  musicVolume:     number
  cosmicIntensity: number
  lineSpacing:     LineSpacing
  language:        AppLanguage
  reduceMotion:    boolean
  haptics:         boolean
  adminMode:       boolean
}

// ── DETECCIÓN AUTOMÁTICA DE IDIOMA ────────────────────────
function detectLanguage(): AppLanguage {
  const nav = typeof navigator === "undefined"
    ? "es"
    : navigator.language || navigator.languages?.[0] || "es"
  const code = nav.slice(0,2).toLowerCase() as AppLanguage
  return SUPPORTED_UI_LANGUAGES.includes(code) ? code : "es"
}

function prefersReducedMotion(): boolean {
  return typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true
}

export const DEFAULTS: Settings = {
  readingMode:     "night", fontSize:        "medium", orbSounds:       true,
  soundVolume:     0.8,
  musicEnabled:    true,
  musicVolume:     0.35,
  cosmicIntensity: 0.7,
  lineSpacing:     "normal", language:        detectLanguage(),
  reduceMotion:    prefersReducedMotion(),
  haptics:         true,
  adminMode:       false,
}

