export const READING_MODE_LABELS: Record<ReadingMode, string> = {
  night: "Noche", twilight: "Penumbra", dawn: "Alba",
}
export const READING_MODE_BG: Record<ReadingMode, string> = {
  night: "#08080c", twilight: "#17131d", dawn: "#f4efe5",
}
export const READING_MODE_TEXT: Record<ReadingMode, string> = {
  night: "#e6e3dd", twilight: "#ddd2e2", dawn: "#302a24",
}
export const READING_MODE_HEADER_BG: Record<ReadingMode, string> = {
  night: "rgba(8,8,12,0.88)", twilight: "rgba(23,19,29,0.88)", dawn: "rgba(244,239,229,0.9)",
}
export const READING_MODE_HEADER_TEXT: Record<ReadingMode, string> = {
  night: "#c8c5c0", twilight: "#cbbfd0", dawn: "#4a4038",
}
export const FONT_SIZE_PX: Record<FontSize, number> = {
  small: 15, medium: 17, large: 20,
}
export const FONT_SIZE_LABELS: Record<FontSize, string> = {
  small: "Pequeña", medium: "Normal", large: "Grande",
}
export const LINE_SPACING_VALUE: Record<LineSpacing, number> = {
  compact: 1.65, normal: 2.10, relaxed: 2.60,
}

// ── PERSISTENCIA ─────────────────────────────────────────
const KEY = "tloque_settings_v2"
const LEGACY_KEY = "novareads_settings"

function load(): Settings {
  try {
    const raw = localStorage.getItem(KEY) || localStorage.getItem(LEGACY_KEY)
    if (!raw) return DEFAULTS
    const parsed = JSON.parse(raw) as Partial<Settings>
    const readingModes: ReadingMode[] = ["night", "twilight", "dawn"]
    const fontSizes: FontSize[] = ["small", "medium", "large"]
    const spacings: LineSpacing[] = ["compact", "normal", "relaxed"]
    const numberInUnitRange = (value: unknown, fallback: number) =>
      typeof value === "number" && Number.isFinite(value) ? Math.max(0, Math.min(1, value)) : fallback
    return {
      readingMode: readingModes.includes(parsed.readingMode as ReadingMode) ? parsed.readingMode as ReadingMode : DEFAULTS.readingMode,
      fontSize: fontSizes.includes(parsed.fontSize as FontSize) ? parsed.fontSize as FontSize : DEFAULTS.fontSize,
      orbSounds: typeof parsed.orbSounds === "boolean" ? parsed.orbSounds : DEFAULTS.orbSounds,
      soundVolume: numberInUnitRange(parsed.soundVolume, DEFAULTS.soundVolume),
      musicEnabled: typeof parsed.musicEnabled === "boolean" ? parsed.musicEnabled : DEFAULTS.musicEnabled,
      musicVolume: numberInUnitRange(parsed.musicVolume, DEFAULTS.musicVolume),
      cosmicIntensity: numberInUnitRange(parsed.cosmicIntensity, DEFAULTS.cosmicIntensity),
      lineSpacing: spacings.includes(parsed.lineSpacing as LineSpacing) ? parsed.lineSpacing as LineSpacing : DEFAULTS.lineSpacing,
      language: SUPPORTED_UI_LANGUAGES.includes(parsed.language as AppLanguage) ? parsed.language as AppLanguage : DEFAULTS.language,
      reduceMotion: typeof parsed.reduceMotion === "boolean" ? parsed.reduceMotion : DEFAULTS.reduceMotion,
      haptics: typeof parsed.haptics === "boolean" ? parsed.haptics : DEFAULTS.haptics,
      adminMode: typeof parsed.adminMode === "boolean" ? parsed.adminMode : false,
    }
  } catch { return DEFAULTS }
}

function persist(s: Settings) {
  try { localStorage.setItem(KEY, JSON.stringify(s)) } catch {}
}

// ── CONTEXTO ─────────────────────────────────────────────
interface SettingsContextValue {
  settings:      Settings
  updateSetting: <K extends keyof Settings>(key: K, value: Settings[K]) => void
  resetSettings: () => void
  t:             (key: string) => string   // función de traducción
}

const SettingsContext = createContext<SettingsContextValue | null>(null)

export function SettingsProvider({ children }: { children: ReactNode }) {
  const [settings, setSettings] = useState<Settings>(load)

  const updateSetting = useCallback(<K extends keyof Settings>(
    key: K, value: Settings[K]
  ) => {
    setSettings(prev => {
      const next = { ...prev, [key]: value }
      persist(next)
      return next
    })
  }, [])

  const resetSettings = useCallback(() => {
    const next = { ...DEFAULTS }
    persist(next); setSettings(next)
  }, [])

  useEffect(() => {
    const meta = LANGUAGE_META[settings.language]
    document.documentElement.lang = meta.locale
    document.documentElement.dir = meta.dir
    document.documentElement.classList.toggle("tloque-reduce-motion", settings.reduceMotion)
  }, [settings.language, settings.reduceMotion])

  // Nunca filtrar español a otra interfaz: ante una clave faltante usamos
  // inglés como respaldo internacional y español solo para la interfaz ES.
  const t = useCallback((key: string): string => {
    const lang = settings.language
    return UI_STRINGS[lang]?.[key]
      ?? (lang === "es" ? UI_STRINGS.es[key] : UI_STRINGS.en[key])
      ?? UI_STRINGS.es[key]
      ?? key
  }, [settings.language])

  return (
    <SettingsContext.Provider value={{ settings, updateSetting, resetSettings, t }}>
      {children}
    </SettingsContext.Provider>
  )
}

export function useSettings(): SettingsContextValue {
  const ctx = useContext(SettingsContext)
  if (!ctx) throw new Error("useSettings debe usarse dentro de <SettingsProvider>")
  return ctx
}
